val LocalLang = staticCompositionLocalOf { Lang.ES }

/** Texto traducido. Los argumentos sustituyen {0}, {1}… */
fun tr(lang: Lang, key: K, vararg args: Any): String {
    var s = catalog[lang]?.get(key) ?: ES[key] ?: key.name
    args.forEachIndexed { i, a -> s = s.replace("{$i}", a.toString()) }
    return s
}

@Composable
fun t(key: K, vararg args: Any): String = tr(LocalLang.current, key, *args)

fun nights(lang: Lang, n: Int): String = tr(lang, if (n == 1) K.NIGHTS_ONE else K.NIGHTS_OTHER, n)

private val regionNames = mapOf(
    "ES" to listOf("España", "Spain", "Espanha", "Espagne"),
    "MX" to listOf("México", "Mexico", "México", "Mexique"),
    "US" to listOf("Estados Unidos", "United States", "Estados Unidos", "États-Unis"),
    "GB" to listOf("Reino Unido", "United Kingdom", "Reino Unido", "Royaume-Uni"),
    "BR" to listOf("Brasil", "Brazil", "Brasil", "Brésil"),
    "CO" to listOf("Colombia", "Colombia", "Colômbia", "Colombie"),
    "AR" to listOf("Argentina", "Argentina", "Argentina", "Argentine"),
    "PT" to listOf("Portugal", "Portugal", "Portugal", "Portugal"),
    "FR" to listOf("Francia", "France", "França", "France"),
    "CA" to listOf("Canadá", "Canada", "Canadá", "Canada"),
