private val catalog = mapOf(Lang.ES to ES, Lang.EN to EN, Lang.PT to PT, Lang.FR to FR)

/** Claves sin traducir en algún idioma (se usa en pruebas). */
fun missingTranslations(): Map<Lang, List<K>> =
    catalog.mapValues { (_, m) -> K.entries.filter { it !in m } }.filterValues { it.isNotEmpty() }
